/** The exact snippet that accepts a finding of `rule` (for the warning output); '' for a rule that cannot be accepted. */
export function acceptHint(rule) {
    return Object.hasOwn(RULE_DOCS, rule) ? findingAcceptanceHint(rule) : '';
}
